import type {
  InferContractRouterInputs,
  InferContractRouterOutputs,
} from "@orpc/contract";
import { z } from "zod";
import { createContractProcedureBuilder } from "../errors";
import { highSchoolSourceSchema } from "../shared/constants";

// Search result hit schemas
const logoVariantSchema = z
  .object({
    name: z.string(),
    url: z.string().url(),
  })
  .strict();

const universityLogoSchema = z
  .object({
    sortOrder: z.number().int(),
    url: z.string().url(),
    providerImageId: z.string(),
    label: z.string().nullable(),
    altText: z.string().nullable(),
    width: z.number().nullable(),
    height: z.number().nullable(),
    variants: z.array(logoVariantSchema),
    theme: z.string().nullable(),
    type: z.string().nullable(),
    metadata: z.record(z.string(), z.string()).nullable(),
  })
  .strict();

const universitySearchHitSchema = z
  .object({
    id: z.string(),
    name: z.string(),
    state: z.string().length(2),
    city: z.string().nullable(),
    isPublic: z.boolean(),
    admissionRate: z.number().min(0).max(1).nullable(),
    website: z.string().nullable(),
    logos: z.array(universityLogoSchema),
    _formatted: z
      .object({
        name: z.string(),
      })
      .optional(),
  })
  .strict();

const highSchoolSearchHitSchema = z
  .object({
    id: z.string(),
    name: z.string(),
    state: z.string().length(2).nullable(),
    city: z.string().nullable(),
    source: highSchoolSourceSchema,
    _formatted: z
      .object({
        name: z.string(),
      })
      .optional(),
  })
  .strict();

const userSearchHitSchema = z
  .object({
    id: z.string(),
    name: z.string(),
    firstName: z.string().nullable(),
    lastName: z.string().nullable(),
    email: z.string().nullable(),
    phoneNumber: z.string().nullable(),
    role: z.string(),
    _formatted: z
      .object({
        name: z.string().optional(),
        firstName: z.string().optional(),
        lastName: z.string().optional(),
        email: z.string().optional(),
      })
      .optional(),
  })
  .strict();

// Search input schema
const globalSearchInputSchema = z
  .object({
    query: z.string().min(1, "Search query is required"),
    filters: z
      .object({
        state: z.string().length(2).optional(),
        type: z.enum(["university", "highschool"]).optional(),
      })
      .strict()
      .optional(),
    limit: z.number().int().min(1).max(50).default(10).optional(),
  })
  .strict();

// Search output schema
const globalSearchOutputSchema = z
  .object({
    universities: z.object({
      hits: z.array(universitySearchHitSchema),
      estimatedTotalHits: z.number().int().nonnegative(),
    }),
    highSchools: z.object({
      hits: z.array(highSchoolSearchHitSchema),
      estimatedTotalHits: z.number().int().nonnegative(),
    }),
    users: z.object({
      hits: z.array(userSearchHitSchema),
      estimatedTotalHits: z.number().int().nonnegative(),
    }),
    query: z.string(),
    processingTimeMs: z.number().nonnegative(),
  })
  .strict();

// Sync and stats schemas
const syncHighSchoolsInputSchema = z
  .object({
    source: highSchoolSourceSchema.optional(),
  })
  .strict()
  .optional();

const syncHighSchoolsOutputSchema = z
  .object({
    jobId: z.string(),
    message: z.string(),
    status: z.enum(["initiated", "failed"]),
  })
  .strict();

const syncSearchIndexesInputSchema = z
  .object({
    clearIndexes: z.boolean().optional(),
  })
  .strict()
  .optional();

const syncSearchIndexesOutputSchema = z
  .object({
    jobId: z.string(),
    message: z.string(),
    status: z.enum(["initiated", "failed"]),
  })
  .strict();

const indexStatsSchema = z
  .object({
    name: z.string(),
    numberOfDocuments: z.number().int().nonnegative(),
    createdAt: z.coerce.string().nullable(),
    updatedAt: z.coerce.string().nullable(),
  })
  .strict();

const getIndexStatsOutputSchema = z
  .object({
    indexes: z.array(indexStatsSchema),
    isHealthy: z.boolean(),
  })
  .strict();

// Contract definition
const contractProcedure = createContractProcedureBuilder();

export const searchContract = {
  global: contractProcedure
    .input(globalSearchInputSchema)
    .output(globalSearchOutputSchema),
  syncHighSchools: contractProcedure
    .input(syncHighSchoolsInputSchema)
    .output(syncHighSchoolsOutputSchema),
  syncSearchIndexes: contractProcedure
    .input(syncSearchIndexesInputSchema)
    .output(syncSearchIndexesOutputSchema),
  getIndexStats: contractProcedure
    .input(z.undefined())
    .output(getIndexStatsOutputSchema),
};

export type SearchContract = typeof searchContract;
export type SearchContractInputs = InferContractRouterInputs<SearchContract>;
export type SearchContractOutputs = InferContractRouterOutputs<SearchContract>;

// Schema exports for reuse in other contracts
export { logoVariantSchema, universityLogoSchema };

// Type exports for easier usage
export type GlobalSearchInput = SearchContractInputs["global"];
export type GlobalSearchOutput = SearchContractOutputs["global"];
export type SyncHighSchoolsInput = SearchContractInputs["syncHighSchools"];
export type SyncHighSchoolsOutput = SearchContractOutputs["syncHighSchools"];
export type SyncSearchIndexesInput = SearchContractInputs["syncSearchIndexes"];
export type SyncSearchIndexesOutput =
  SearchContractOutputs["syncSearchIndexes"];
export type GetIndexStatsOutput = SearchContractOutputs["getIndexStats"];

export type UniversitySearchHit = z.infer<typeof universitySearchHitSchema>;
export type HighSchoolSearchHit = z.infer<typeof highSchoolSearchHitSchema>;
export type UserSearchHit = z.infer<typeof userSearchHitSchema>;
export type IndexStats = z.infer<typeof indexStatsSchema>;
